// DX-Ball service worker (generated by web/build-pwa.mjs). VERSION changes with every build (hash of index.html), so the
// browser sees a new sw.js, installs it, and the old cache is dropped on activate.
const VERSION = '1263be1988fc';
const CACHE = 'dxball-' + VERSION;
// Pre-cached on install, relative to this file. The page itself is stored once, as index.html; every navigation within
// the scope ('./', './?x=1', './index.html') is answered with that one entry (it is ~40 MB, so no duplicates).
const SHELL = ['index.html', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png', 'icon-maskable-512.png', 'apple-touch-icon.png'];
const SCOPE = new URL('./', self.location).href;   // e.g. https://rgoliveira.com/dxball/
const PAGE = new URL('index.html', SCOPE).href;

self.addEventListener('install', (e) => {
  // No skipWaiting(): the new version takes over when all tabs/app windows of the old one are closed, so a running
  // game is never swapped mid-play. cache:'reload' bypasses the HTTP cache so a new version never stores a stale page.
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL.map((u) => new Request(u, { cache: 'reload' })))));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('dxball-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  // Only GETs inside this scope (same origin, under /dxball/); everything else goes straight to the network.
  if (req.method !== 'GET' || !req.url.startsWith(SCOPE)) return;
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const key = req.mode === 'navigate' ? PAGE : req;      // all navigations are the same single-file document
    const hit = await cache.match(key);
    if (hit) return hit;                                   // cache-first
    const res = await fetch(req);
    // Keep a copy of successful full responses (clone() before the body is read; the original goes to the page).
    // Skip partial (206), error and opaque responses. Not awaited, so the page is not delayed by the cache write.
    if (res.status === 200 && res.type === 'basic') e.waitUntil(cache.put(key, res.clone()).catch(() => {}));
    return res;
  })());
});
